+/// The one through-opening of the retained die plate, matched to the selected
+/// rim. Reading only the picked loop could post a cut through a blind floor or
+/// on an unrelated face, so compare it with the full-height hole of the prism.
+fn die_opening<'r>(
+    region: &'r Region,
+    job: &job::GenJob,
+    lo: [f64; 2],
+    hi: [f64; 2],
+) -> Result<&'r Loop, String> {
+    let loops = region.loops();
+    if loops.len() != 2 || loops.iter().filter(|r| r.area() > 0.0).count() != 1 {
+        return Err("The native wire EDM job requires one retained die plate with exactly one through-opening".into());
+    }
+    if loops
+        .iter()
+        .flat_map(|r| r.points())
+        .any(|p| p.x < lo[0] || p.x > hi[0] || p.y < lo[1] || p.y > hi[1])
+    {
+        return Err("The retained die plate must fit inside the stock".into());
+    }
+    let hole = loops
+        .iter()
+        .find(|r| r.area() < 0.0)
+        .ok_or("The native wire EDM job requires a through-opening in the retained plate")?;
+    let (picked, open, _) = job
+        .contour_sel
+        .as_ref()
+        .ok_or("Select the complete rim of the die opening")?
+        .as_ref()
+        .map_err(ToString::to_string)?;
+    let [picked] = picked.as_slice() else {
+        return Err("Select the edge chains of exactly one closed die opening rim".into());
+    };
+    let footprint = |r: &Loop| Region::new(vec![r.clone()]).map_err(|e| e.to_string());
+    let (a, b) = (footprint(hole)?, footprint(picked)?);
+    if !open.is_empty()
+        || !a.difference(&b).is_ok_and(|r| r.is_empty())
+        || !b.difference(&a).is_ok_and(|r| r.is_empty())
+    {
+        return Err(
+            "The selected chains must match the full through-opening of the retained die plate"
+                .into(),
+        );
+    }
+    Ok(hole)
+}
+
+/// The one selected straight wall of the retained prism for an open cutoff.
+/// The whole retained cap must lie on the side away from the kerf, and the
+/// model must lie inside the stock.
+fn cutoff_edge<'j>(
+    region: &Region,
+    job: &'j job::GenJob,
+    side: agie::AgieSide,
+    lo: [f64; 2],
+    hi: [f64; 2],
+) -> Result<&'j [crate::geo2d::Point2], String> {
+    let (rings, open, _) = job
+        .contour_sel
+        .as_ref()
+        .ok_or("Select one retained cutoff edge")?
+        .as_ref()
+        .map_err(ToString::to_string)?;
+    let [chain] = open.as_slice() else {
+        return Err("The open cutoff requires exactly one open cutoff edge".into());
+    };
+    let [a, b] = chain.as_slice() else {
+        return Err("The open cutoff requires a single straight edge".into());
+    };
+    let [body] = region.loops() else {
+        return Err("The open cutoff requires one through prism without holes".into());
+    };
+    let vertices = body.points();
+    let has_edge = vertices
+        .iter()
+        .zip(vertices.iter().cycle().skip(1))
+        .any(|(p, q)| (p == a && q == b) || (p == b && q == a));
+    let waste = if side == agie::AgieSide::Left { 1. } else { -1. };
+    if !rings.is_empty()
+        || !has_edge
+        || vertices.iter().any(|p| {
+            p.x < lo[0]
+                || p.x > hi[0]
+                || p.y < lo[1]
+                || p.y > hi[1]
+                || waste * ((b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x)) > 0.
+        })
+    {
+        return Err("The selected cutoff must span a full retained wall with the kerf on the waste side and the model within stock".into());
+    }
+    Ok(chain.as_slice())
+}

