+fn run(directory: &Path, script: &str) -> std::process::Output {
+    let examples = directory.join("examples/agie");
+    fs::create_dir_all(&examples).unwrap();
+    for (file, data) in [
+        ("cutoff-lower.obj", LOWER_MESH),
+        ("cutoff-upper.obj", UPPER_MESH),
